```javascript
const audited = inputs.matchedPairs.map((p) => {
  const feePct = (p.gatewayFee / (p.ledgerGross || 1)) * 100;
  const compliant = feePct <= 2.5;
  return {
    ...p,
    feePct: Math.round(feePct * 100) / 100,
    isCompliant: compliant,
  };
});
return { auditedBatches: audited };
```

